css:
/* From Uiverse.io by csemszepp  - Website: https://codepen.io/Adir-SL - Name: Adir - Tags: tooltip, animation, minimalist */
.__UIV_SCOPE__ .container {
  background-color: black;
  color: rgb(132, 170, 218);
  font-family: "Inter", sans-serif;
  font-size: 14px;
}
.__UIV_SCOPE__ .container::before {
  content: "Hover or tap the icons.";
  font-size: 14px;
  position: absolute;
  left: 50%;
  top: calc(50% - 100px);
  transform: translate(-50%, -50%);
}
.__UIV_SCOPE__ .container::after {
  position: absolute;
  bottom: 36px;
  right: 36px;
}
.__UIV_SCOPE__ #wrapper {
  display: flex;
  align-items: center;
  justify-content: center;
  position: absolute;
  inset: 0;
}
.__UIV_SCOPE__ header {
  width: 340px;
  padding: 0 16px;
  display: flex;
  border: 1px solid rgb(83, 100, 124);
  border-radius: 16px;
}
.__UIV_SCOPE__ .iconDiv {
  height: 36px;
  width: 36px;
  margin-top: 20px;
  margin-bottom: 20px;
  margin-left: 4px;
  padding: 4px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  overflow: hidden;
  cursor: pointer;
  transition: width 300ms ease-in-out 0s, background-color 300ms linear 200ms;
}
.__UIV_SCOPE__ .iconSVG {
  height: 36px;
  aspect-ratio: 1 / 1;
}
.__UIV_SCOPE__ .iconDiv:hover,
.__UIV_SCOPE__ .iconDiv:focus-visible {
  width: 142px;
  background-color: rgb(34, 52, 77);
  transition: width 300ms ease-in-out 0s, background-color 100ms linear 0s;
}
.__UIV_SCOPE__ .iconDiv:focus-visible {
  outline: 1px solid rgb(34, 52, 77);
  outline-offset: 4px;
}
.__UIV_SCOPE__ .iconDiv:active {
  opacity: 0.9;
}
.__UIV_SCOPE__ .iconDiv::after {
  content: attr(tooltip);
  margin-left: 12px;
  animation: fadeIn 600ms linear forwards;
}
.__UIV_SCOPE__ .spacer {
  flex-grow: 1;
}
.__UIV_SCOPE__ .divider {
  height: 36px;
  width: 1px;
  margin: 24px 18px;
  background-color: rgb(83, 100, 124);
}

@keyframes fadeIn {
  0% {
    opacity: 0;
  }
  50% {
    opacity: 0;
  }
  100% {
    opacity: 1;
  }
}
.__UIV_SCOPE__ .text {
  padding-left: 10px;
}
